import { act, screen } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import { render } from "../../../test-utils/render";
import ShortSlideDown from "../index";

describe("ShortSlideDown", () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("renders only the first word of the first phrase initially", () => {
    render(<ShortSlideDown phrases={["Hello World", "Second Phrase"]} />);

    expect(screen.getByText("Hello")).toBeInTheDocument();
    expect(screen.queryByText("World")).not.toBeInTheDocument();
  });

  it("reveals subsequent words as the build schedule advances", () => {
    render(<ShortSlideDown phrases={["Hello World"]} />);

    act(() => {
      vi.advanceTimersByTime(500);
    });

    expect(screen.getByText("World")).toBeInTheDocument();
  });

  it("cycles to the next phrase after the build completes and interval elapses", () => {
    const { container } = render(
      <ShortSlideDown interval={100} phrases={["Hi", "Bye"]} />
    );

    expect(container.textContent).toContain("Hi");

    act(() => {
      vi.advanceTimersByTime(360 + 100 + 320 + 180);
    });

    expect(container.textContent).toContain("Bye");
  });

  it("wraps back to the first phrase after the last one", () => {
    const { container } = render(
      <ShortSlideDown interval={100} phrases={["Hi", "Bye"]} />
    );

    act(() => {
      vi.advanceTimersByTime(360 + 100 + 320 + 180);
    });
    act(() => {
      vi.advanceTimersByTime(360 + 100 + 320 + 180);
    });

    expect(container.textContent).toContain("Hi");
  });

  it("applies a custom className to the wrapper", () => {
    const { container } = render(
      <ShortSlideDown className="custom-class" phrases={["Hi"]} />
    );

    expect(container.querySelector("span.custom-class")).toBeInTheDocument();
  });

  it("marks the wrapper as an aria-live region", () => {
    const { container } = render(<ShortSlideDown phrases={["Hi"]} />);

    expect(
      container.querySelector("span[aria-live='polite']")
    ).toBeInTheDocument();
  });
});

describe("ShortSlideDown with reduced motion", () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.resetModules();
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.doUnmock("motion/react");
  });

  it("shows the full phrase immediately and advances only via the interval", async () => {
    vi.doMock("motion/react", async (importOriginal) => {
      const actual = await importOriginal<typeof import("motion/react")>();
      return { ...actual, useReducedMotion: () => true };
    });
    const { default: ShortSlideDownReduced } = await import("../index");

    render(
      <ShortSlideDownReduced
        interval={200}
        phrases={["Hello there", "Goodbye now"]}
      />
    );

    expect(screen.getByText("Hello")).toBeInTheDocument();
    expect(screen.getByText("there")).toBeInTheDocument();

    act(() => {
      vi.advanceTimersByTime(200);
    });

    expect(screen.getByText("Goodbye")).toBeInTheDocument();
    expect(screen.getByText("now")).toBeInTheDocument();
  });

  it("has no accessibility violations", async () => {
    vi.useRealTimers();
    const { container } = render(<ShortSlideDown phrases={["Hello World"]} />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });
});

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";

export interface ShortSlideDownProps {
  className?: string;
  /** Interval between phrase completions in milliseconds. */
  interval?: number;
  phrases: string[];
}

const BUILD_EASE = [0.2, 0.8, 0.2, 1] as const;
const EXIT_EASE = [0.4, 0, 0.2, 1] as const;

/**
 * ShortSlideDown — each new word drops in from above into its own centered line,
 * pushing the stack downward until a centered multi-line composition locks in place.
 * From the animate-text catalog (`short-slide-down`).
 */
export default function ShortSlideDown({
  phrases,
  className = "",
  interval = 2500,
}: ShortSlideDownProps) {
  const [phraseIndex, setPhraseIndex] = useState(0);
  const [wordCount, setWordCount] = useState(1);
  const [exiting, setExiting] = useState(false);
  const shouldReduceMotion = useReducedMotion();

  const currentPhrase = phrases[phraseIndex] ?? "";
  const words = currentPhrase.split(" ");

  // biome-ignore lint/correctness/useExhaustiveDependencies: words.length drives the build schedule
  useEffect(() => {
    if (shouldReduceMotion) {
      const holdId = setTimeout(() => {
        setPhraseIndex((prev) => (prev + 1) % phrases.length);
      }, interval);
      return () => clearTimeout(holdId);
    }

    setWordCount(1);
    setExiting(false);

    const buildTimers: ReturnType<typeof setTimeout>[] = [];

    for (let i = 1; i < words.length; i++) {
      buildTimers.push(
        setTimeout(() => {
          setWordCount(i + 1);
        }, i * 500)
      );
    }

    const totalBuild = (words.length - 1) * 500 + 360;
    const holdId = setTimeout(() => {
      setExiting(true);
      setTimeout(() => {
        setPhraseIndex((prev) => (prev + 1) % phrases.length);
        setWordCount(1);
        setExiting(false);
      }, 320 + 180);
    }, totalBuild + interval);

    buildTimers.push(holdId);
    return () => {
      for (const t of buildTimers) {
        clearTimeout(t);
      }
    };
  }, [phraseIndex, phrases.length, interval, shouldReduceMotion, words.length]);

  const visibleWords = shouldReduceMotion ? words : words.slice(0, wordCount);
  const restingAnimate = shouldReduceMotion
    ? { opacity: 1 }
    : { filter: "blur(0px)", opacity: 1, scale: 1, y: 0 };
  const exitAnimate = {
    filter: "blur(1.2px)",
    opacity: 0,
    transition: { duration: 0.32, ease: EXIT_EASE },
    y: 10,
  };

  return (
    <span
      aria-live="polite"
      className={`flex flex-col items-center ${className}`}
      style={{ gap: 12 }}
    >
      <AnimatePresence mode="popLayout">
        {visibleWords.map((word, i) => (
          <motion.span
            animate={exiting ? exitAnimate : restingAnimate}
            initial={
              shouldReduceMotion
                ? { opacity: 1 }
                : { filter: "blur(2.4px)", opacity: 0, scale: 0.992, y: -28 }
            }
            // biome-ignore lint/suspicious/noArrayIndexKey: word position is the stable identity within a phrase
            key={`${phraseIndex}-${i}`}
            layout
            style={{ display: "block" }}
            transition={
              shouldReduceMotion
                ? { duration: 0 }
                : {
                    duration: i === 0 ? 0.36 : 0.5,
                    ease: BUILD_EASE,
                    layout: { duration: 0.5, ease: BUILD_EASE },
                  }
            }
          >
            {word}
          </motion.span>
        ))}
      </AnimatePresence>
    </span>
  );
}

