      }
    }}
    step={step}
    value={value === undefined ? undefined : [value]}
  >
    <SliderControl>
      <SliderTrack>
        <SliderIndicator />
        <SliderThumb aria-label={ariaLabel ?? "Value"} />
      </SliderTrack>
    </SliderControl>
  </SliderRoot>
);

