      </SmoothButton>
    );
    expect(
      classesOf(accent.container.querySelector("button") as HTMLElement)
    ).toContain("[--btn-fg:var(--color-on-brand)]");
    const destructive = render(
      <SmoothButton color="destructive" variant="solid">
